-- Create "users" table
CREATE TABLE "users" ("id" uuid NOT NULL, "email" character varying NOT NULL, "time_zone" character varying NOT NULL DEFAULT 'UTC', "created_at" timestamptz NOT NULL, PRIMARY KEY ("id"));
-- Create index "users_email_key" to table: "users"
CREATE UNIQUE INDEX "users_email_key" ON "users" ("email");
-- Create "device_authorizations" table
CREATE TABLE "device_authorizations" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "device_code_hash" bytea NOT NULL, "user_code" character varying NOT NULL, "created_at" timestamptz NOT NULL, "expires_at" timestamptz NOT NULL, "user_id" uuid NULL, PRIMARY KEY ("id"), CONSTRAINT "device_authorizations_users_device_authorizations" FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON UPDATE NO ACTION ON DELETE SET NULL);
-- Create index "device_authorizations_device_code_hash_key" to table: "device_authorizations"
CREATE UNIQUE INDEX "device_authorizations_device_code_hash_key" ON "device_authorizations" ("device_code_hash");
-- Create index "device_authorizations_user_code_key" to table: "device_authorizations"
CREATE UNIQUE INDEX "device_authorizations_user_code_key" ON "device_authorizations" ("user_code");
-- Create "identities" table
CREATE TABLE "identities" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "provider" character varying NOT NULL, "subject" character varying NOT NULL, "created_at" timestamptz NOT NULL, "user_id" uuid NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "identities_users_identities" FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION);
-- Create index "identity_provider_subject" to table: "identities"
CREATE UNIQUE INDEX "identity_provider_subject" ON "identities" ("provider", "subject");
-- Create "sessions" table
CREATE TABLE "sessions" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "token_hash" bytea NOT NULL, "created_at" timestamptz NOT NULL, "expires_at" timestamptz NOT NULL, "revoked_at" timestamptz NULL, "user_id" uuid NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "sessions_users_sessions" FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION);
-- Create index "sessions_token_hash_key" to table: "sessions"
CREATE UNIQUE INDEX "sessions_token_hash_key" ON "sessions" ("token_hash");
-- Create "task_events" table
CREATE TABLE "task_events" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "task_id" uuid NOT NULL, "action" character varying NOT NULL, "before" jsonb NULL, "after" jsonb NULL, "created_at" timestamptz NOT NULL, "session_id" bigint NULL, "user_id" uuid NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "task_events_sessions_task_events" FOREIGN KEY ("session_id") REFERENCES "sessions" ("id") ON UPDATE NO ACTION ON DELETE SET NULL, CONSTRAINT "task_events_users_task_events" FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION);
-- Create index "taskevent_session_id" to table: "task_events"
CREATE INDEX "taskevent_session_id" ON "task_events" ("session_id");
-- Create index "taskevent_user_id_task_id" to table: "task_events"
CREATE INDEX "taskevent_user_id_task_id" ON "task_events" ("user_id", "task_id");
-- Create "tasks" table
CREATE TABLE "tasks" ("id" uuid NOT NULL, "description" character varying NOT NULL, "status" character varying NOT NULL, "project" character varying NOT NULL DEFAULT '', "priority" character varying NOT NULL DEFAULT '', "estimate_minutes" bigint NULL, "entry" timestamptz NOT NULL, "modified" timestamptz NOT NULL, "due" timestamptz NULL, "scheduled" timestamptz NULL, "start" timestamptz NULL, "wait" timestamptz NULL, "until" timestamptz NULL, "end" timestamptz NULL, "tags" jsonb NULL, "annotations" jsonb NULL, "depends" jsonb NULL, "recurrence" character varying NOT NULL DEFAULT '', "parent" uuid NULL, "extra" jsonb NULL, "user_id" uuid NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "tasks_users_tasks" FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION);
-- Create index "task_parent" to table: "tasks"
CREATE INDEX "task_parent" ON "tasks" ("parent");
-- Create index "task_user_id_status" to table: "tasks"
CREATE INDEX "task_user_id_status" ON "tasks" ("user_id", "status");
